//! Provider secrets at rest (NOWPayments API key and IPN secret): AES-256-GCM with the service key
//! `WALLET_SECRETS_KEY` (64 hex characters, generated by deploy/deploy.sh like the gateway's KYC key).
//!
//! Stored form: `v1:<hex of 12-byte nonce || ciphertext || 16-byte tag>`. The associated data names the tenant and
//! the setting (`<tenant_id>:<name>`), so a value copied onto another tenant or another setting fails to open.
//! Secrets never leave the service: the admin API only shows whether one is set and its last 4 characters.

use ring::aead::{AES_256_GCM, Aad, LessSafeKey, NONCE_LEN, Nonce, UnboundKey};
use sha2::{Digest, Sha256};

const PREFIX: &str = "v1:";

/// The data key. `None` in production when `WALLET_SECRETS_KEY` is missing or malformed: secrets can't be saved
/// or used then (the Back Office says so).
pub fn key(cfg: &crate::config::Config) -> Option<[u8; 32]> {
    let raw = cfg.secrets_key.trim();
    if raw.len() == 64 && raw.chars().all(|c| c.is_ascii_hexdigit()) {
        let mut out = [0u8; 32];
        for (i, chunk) in raw.as_bytes().chunks(2).enumerate() {
            out[i] = u8::from_str_radix(std::str::from_utf8(chunk).ok()?, 16).ok()?;
        }
        return Some(out);
    }
    if raw.is_empty() && cfg.dev_mode {
        // development only: a fixed key, so local secrets survive a restart (never used in production)
        return Some(Sha256::digest(b"kalks-wallet-development-secrets-key").into());
    }
    None
}

fn aead(key: &[u8; 32]) -> LessSafeKey {
    LessSafeKey::new(UnboundKey::new(&AES_256_GCM, key).expect("32-byte AES-256 key"))
}

pub fn seal(key: &[u8; 32], context: &str, plain: &str) -> anyhow::Result<String> {
    let mut nonce = [0u8; NONCE_LEN];
    getrandom::fill(&mut nonce).map_err(|_| anyhow::anyhow!("OS randomness unavailable"))?;
    let mut buf = plain.as_bytes().to_vec();
    aead(key)
        .seal_in_place_append_tag(Nonce::assume_unique_for_key(nonce), Aad::from(context.as_bytes()), &mut buf)
        .map_err(|_| anyhow::anyhow!("encryption failed"))?;
    let mut out = nonce.to_vec();
    out.extend_from_slice(&buf);
    Ok(format!("{PREFIX}{}", crate::chain::hex_encode(&out)))
}

pub fn open(key: &[u8; 32], context: &str, sealed: &str) -> anyhow::Result<String> {
    let hex = sealed.strip_prefix(PREFIX).ok_or_else(|| anyhow::anyhow!("unknown secret format"))?;
    let bytes = hex_decode(hex).ok_or_else(|| anyhow::anyhow!("corrupt secret"))?;
    if bytes.len() < NONCE_LEN + 16 {
        anyhow::bail!("corrupt secret");
    }
    let nonce: [u8; NONCE_LEN] = bytes[..NONCE_LEN].try_into()?;
    let mut buf = bytes[NONCE_LEN..].to_vec();
    let plain = aead(key)
        .open_in_place(Nonce::assume_unique_for_key(nonce), Aad::from(context.as_bytes()), &mut buf)
        .map_err(|_| anyhow::anyhow!("the secret can't be decrypted with this WALLET_SECRETS_KEY"))?;
    Ok(String::from_utf8(plain.to_vec())?)
}

fn hex_decode(s: &str) -> Option<Vec<u8>> {
    if !s.len().is_multiple_of(2) {
        return None;
    }
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(s.get(i..i + 2)?, 16).ok()).collect()
}

/// The last 4 characters, shown as "…1234" in the Back Office.
pub fn last4(secret: &str) -> String {
    let chars: Vec<char> = secret.chars().collect();
    chars[chars.len().saturating_sub(4)..].iter().collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trip_and_context_binding() {
        let k = [7u8; 32];
        let s = seal(&k, "1:api_key", "NP-KEY-ABCD-1234").unwrap();
        assert!(s.starts_with("v1:") && !s.contains("ABCD"));
        assert_eq!(open(&k, "1:api_key", &s).unwrap(), "NP-KEY-ABCD-1234");
        // another tenant / setting or another key can't open it
        assert!(open(&k, "2:api_key", &s).is_err());
        assert!(open(&k, "1:ipn_secret", &s).is_err());
        assert!(open(&[8u8; 32], "1:api_key", &s).is_err());
        // two seals of the same value differ (random nonce)
        assert_ne!(seal(&k, "1:api_key", "x").unwrap(), seal(&k, "1:api_key", "x").unwrap());
        assert_eq!(last4("abcdef123456"), "3456");
        assert_eq!(last4("ab"), "ab");
    }

    #[test]
    fn production_needs_a_key() {
        let mut c = crate::config::Config::for_tests("postgres://x/y");
        c.secrets_key = String::new();
        c.dev_mode = false;
        assert!(key(&c).is_none());
        c.dev_mode = true;
        assert!(key(&c).is_some());
        c.secrets_key = "ab".repeat(32);
        assert_eq!(key(&c), Some([0xab; 32]));
        c.secrets_key = "not-hex".into();
        assert!(key(&c).is_none());
    }
}
